  }
  if(!tokenCandidates.length&&ownTemplates?.[0]){
    tokenCandidates.push({skill,item:ownTemplates[0]});
  }

  let tIdx=0;
  for(const slot of tokenSlots){
    if(slot<list.length&&tokenCandidates.length){
      let q=null, cand=null;
