    function normalizeUnits(s, course) {
      var tx = String(s || '').toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, ' ');
      if (course === 'ja') {
        tx = tx.replace(/\s+/g, '');
        var grams = [];
        for (var i = 0; i + 1 < tx.length; i++) grams.push(tx.slice(i, i + 2));
        return grams;
      }
      return tx.split(/\s+/).filter(Boolean);
