      }
      if (!recognition) return;
      var rec = recognition;
      recognition = null;
      try {
        rec.onstart = null;
        rec.onend = null;
        rec.onerror = null;
        rec.onresult = null;
        rec.onaudiostart = null;
        rec.onsoundstart = null;
        rec.onspeechstart = null;
        rec.onspeechend = null;
        rec.onsoundend = null;
        rec.onaudioend = null;
