>' + c.sessions.slice().reverse().map(function (x) { return '<li><b>' + esc(x.title) + '</b><small>' + x.itemIds.length + ' soal · ' + x.minutes + ' menit · ' + new Date(x.sentAt).toLocaleDateString('id-ID') + '</small></li>'; }).join('') + '</ul></div>' : '');
